#!/usr/bin/env bash
# step97 — Batch 1: home page. Orders-delivered = base + REAL delivered orders
# only (no fake growth/ticker), "View all" drops the count, mobile category grid
# no longer clips. Also prints product.ejs + order.ejs (read-only) for the next
# step (de-duplicating the doubled MAC / credentials blocks). Rolls back.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step97-$TS
mkdir -p "$BAK/views"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/views/home.ejs" "$BAK/views/home.ejs"
restore(){ echo "!! rollback"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/views/home.ejs" "$APP/views/home.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> overwrite home.ejs (real delivered counter + view-all + mobile cats)"
base64 -d > "$APP/views/home.ejs" <<'B64'

B64

echo "==> patch server.js (real delivered count in homeData)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('deliveredReal')>=0){ console.log('   already patched'); }
else {
  const a1="  const reviewCount = (await pool.query('SELECT count(*)::int n FROM reviews WHERE approved')).rows[0].n;";
  if(s.indexOf(a1)<0){ console.error('!! reviewCount anchor not found'); process.exit(2); }
  s=s.replace(a1, a1+"\n  const deliveredReal = (await pool.query(\"SELECT count(*)::int n FROM orders WHERE status='delivered'\")).rows[0].n;");
  const a2="shellJson, reviewCount };";
  if(s.indexOf(a2)<0){ console.error('!! homeData return anchor not found'); process.exit(3); }
  s=s.replace(a2, "shellJson, reviewCount, deliveredReal };");
  fs.writeFileSync(f,s); console.log('   server.js patched');
}
NODE

echo "==> node --check + ejs compile + restart"
node --check "$APP/server.js"
node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$APP/views/home.ejs','utf8'),{filename:'x'});console.log('   home compiles');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
trap - ERR
echo "==> step97 OK — home counter real + view-all + mobile cats. Backup: $BAK"
echo
echo "########## BELOW IS READ-ONLY: product.ejs + order.ejs (for de-dup step) ##########"
echo "===== views/product.ejs ====="
cat "$APP/views/product.ejs"
echo "===== END product.ejs ====="
echo "===== views/order.ejs ====="
cat "$APP/views/order.ejs"
echo "===== END order.ejs ====="
